  "melon-flight": {"title":"A clearer way to choose a flight","intro":"Melon flight search redesign. Bringing schedules, fares, and flight details into a clearer desktop booking experience.","editorial":true,"tags":["Melon","SaaS","Traveltech"],"overview":[],"sections":[["Compare the journey at a glance","A consistent result layout puts the route, timing, and price together so travellers can compare their options.","Melon"],["Look closer without losing context","Flight details give the journey room to breathe, with the information needed before choosing a fare.","Melon"],["Know what the fare includes","Fare details make the differences between options easier to inspect before moving into checkout.","Melon"]],"images":["melon-flight/0.png","melon-flight/1.png","melon-flight/2.png"],"imageAlts":["Compare the journey at a glance","Look closer without losing context","Know what the fare includes"],"layout":[["media",[0]],["section",1],["media",[1]],["section",2],["media",[2]]]},
